package com.prayersoundswapper;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class NativeSoundReplayGuardTest
{
	@Test
	public void bypassesMarkedReplayOnce()
	{
		PrayerSoundSwapperPlugin plugin = new PrayerSoundSwapperPlugin();

		plugin.markReplayedNativeSound(PrayerSoundSwap.PROTECT_FROM_MAGIC.getSoundId());

		assertTrue(plugin.consumeReplayedNativeSound(PrayerSoundSwap.PROTECT_FROM_MAGIC.getSoundId()));
		assertFalse(plugin.consumeReplayedNativeSound(PrayerSoundSwap.PROTECT_FROM_MAGIC.getSoundId()));
	}

	@Test
	public void doesNotBypassUnmarkedSound()
	{
		PrayerSoundSwapperPlugin plugin = new PrayerSoundSwapperPlugin();

		assertFalse(plugin.consumeReplayedNativeSound(PrayerSoundSwap.PROTECT_FROM_MAGIC.getSoundId()));
	}

	@Test
	public void tracksReplayPerSoundId()
	{
		PrayerSoundSwapperPlugin plugin = new PrayerSoundSwapperPlugin();

		plugin.markReplayedNativeSound(PrayerSoundSwap.PROTECT_FROM_MELEE.getSoundId());

		assertFalse(plugin.consumeReplayedNativeSound(PrayerSoundSwap.PROTECT_FROM_MAGIC.getSoundId()));
		assertTrue(plugin.consumeReplayedNativeSound(PrayerSoundSwap.PROTECT_FROM_MELEE.getSoundId()));
	}

	@Test
	public void skipsReplayWhenReplacementAlreadyPlayedNaturally()
	{
		PrayerSoundSwapperPlugin plugin = new PrayerSoundSwapperPlugin();

		plugin.markNativeSoundPlayedNaturally(PrayerSoundSwap.PROTECT_FROM_MELEE.getSoundId());

		assertFalse(plugin.shouldQueueNativeSoundSwap(PrayerSoundSwap.PROTECT_FROM_MELEE.getSoundId()));
	}

	@Test
	public void naturalReplacementCancelsQueuedReplay()
	{
		PrayerSoundSwapperPlugin plugin = new PrayerSoundSwapperPlugin();

		assertTrue(plugin.shouldQueueNativeSoundSwap(PrayerSoundSwap.PROTECT_FROM_MELEE.getSoundId()));

		plugin.markNativeSoundPlayedNaturally(PrayerSoundSwap.PROTECT_FROM_MELEE.getSoundId());

		assertFalse(plugin.consumeQueuedNativeSoundSwap(PrayerSoundSwap.PROTECT_FROM_MELEE.getSoundId()));
	}

	@Test
	public void coalescesDuplicateQueuedReplays()
	{
		PrayerSoundSwapperPlugin plugin = new PrayerSoundSwapperPlugin();

		assertTrue(plugin.shouldQueueNativeSoundSwap(PrayerSoundSwap.PROTECT_FROM_MELEE.getSoundId()));
		assertFalse(plugin.shouldQueueNativeSoundSwap(PrayerSoundSwap.PROTECT_FROM_MELEE.getSoundId()));
		assertTrue(plugin.consumeQueuedNativeSoundSwap(PrayerSoundSwap.PROTECT_FROM_MELEE.getSoundId()));
	}
}

package com.prayersoundswapper;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PrayerSoundIdsTest
{
	@Test
	public void allowsKnownPrayerSoundIds()
	{
		assertTrue(PrayerSoundIds.isReplaceable(1982));
		assertTrue(PrayerSoundIds.isReplaceable(2266));
		assertTrue(PrayerSoundIds.isReplaceable(2675));
		assertTrue(PrayerSoundIds.isReplaceable(2685));
		assertTrue(PrayerSoundIds.isReplaceable(3825));
		assertTrue(PrayerSoundIds.isReplaceable(10100));
	}

	@Test
	public void rejectsNonPrayerSoundIds()
	{
		assertFalse(PrayerSoundIds.isReplaceable(97));
		assertFalse(PrayerSoundIds.isReplaceable(2692));
	}
}

